function IdolLive3D_Input:__init( idolLive3D_Main_ )

    self.idolLive3D_Main = idolLive3D_Main_

    self.OnSimpleTapCallBacks = {}  -- void CB(gesture)[]
    self.OnSwipeCallBacks = {}      -- void CB(gesture)[]
    self.OnPinchCallBacks = {}      -- void CB(float deltaPinch)[]  参数: 正:pinchOut  负:pinchIn

    IdolLive3D_States.InitInputFlags()
    self:_RegistEvent()
    self:InitEasyTouch()
end

-- 需外部调用 Delete()
function IdolLive3D_Input:__delete()

    self:_UnregistEvent()
    self:ResetEasyTouch()

    self.OnSimpleTapCallBacks = {}
    self.OnSwipeCallBacks = {}
    self.OnPinchCallBacks = {}
end



function IdolLive3D_Input:InitEasyTouch()
    --printError("IdolLive3D_Input:InitEasyTouch")

    EasyTouch.SetEnableAutoSelect(true)
    -- 开启: pc端模拟触控
    self.cachedEnableSimulation = EasyTouch.GetSecondeFingerSimulation()
    EasyTouch.SetSecondFingerSimulation(true)
    -- 开启: 双指:
    self.cachedEnable2FingersGesture = EasyTouch.GetEnable2FingersGesture()
    EasyTouch.SetEnable2FingersGesture(true)
    -- 
    self.cachedAlwaysSendSwipe = EasyTouch.instance.alwaysSendSwipe
    EasyTouch.instance.alwaysSendSwipe = true

    Input.multiTouchEnabled = true
end



function IdolLive3D_Input:ResetEasyTouch()
    --printError("IdolLive3D_Input:ResetEasyTouch")

    -- 恢复原来的: pc端模拟触控设置:
    if type(self.cachedEnableSimulation) == "boolean" then 
        EasyTouch.SetSecondFingerSimulation(self.cachedEnableSimulation)
    else
        printError("koko -- cachedEnableSimulation 丢失了")
    end
    -- 恢复原来的: 双指设置:
    if type(self.cachedEnable2FingersGesture) == "boolean" then 
        EasyTouch.SetEnable2FingersGesture(self.cachedEnable2FingersGesture)
    else 
        printError("koko -- cachedEnable2FingersGesture 丢失了")
    end 
    --
    if type(self.cachedAlwaysSendSwipe) == "boolean" then 
        EasyTouch.instance.alwaysSendSwipe = self.cachedAlwaysSendSwipe
    else 
        printError("koko -- cachedAlwaysSendSwipe 丢失了")
    end 

    Input.multiTouchEnabled = false
end



function IdolLive3D_Input:SelfUpdate()

    if IdolLive3D_States.isWindowsPlatform then 

        if Mathf.Approximately(Input.mouseScrollDelta.y, 0.0) == false then 

            --print("koko 滚轮: " .. Input.mouseScrollDelta:ToString() ) -- 前滚为 -1, 后滚为 +1 
            if #self.OnPinchCallBacks > 0 then
                for i=1,#self.OnPinchCallBacks do 
                    self.OnPinchCallBacks[i]( - mouseScrollStep * Input.mouseScrollDelta.y )
                end
            end

        end
    end
end

