function IdolLive3D_Input:Add_OnSimpleTapCallBack( cb_ )
    if type(cb_) ~= "function" then 
        printError("koko- 参数异常");
        return
    end 
    table.insert( self.OnSimpleTapCallBacks, cb_ )
end

function IdolLive3D_Input:Add_OnSwipeCallBack( cb_ )
    if type(cb_) ~= "function" then 
        printError("koko- 参数异常");
        return
    end 
    --printError("绑定 swipe")
    table.insert( self.OnSwipeCallBacks, cb_ )
end

function IdolLive3D_Input:Add_OnPinchCallBack( cb_ )
    if type(cb_) ~= "function" then 
        printError("koko- 参数异常");
        return
    end 
    table.insert( self.OnPinchCallBacks, cb_ )
end



function IdolLive3D_Input:_RegistEvent()

    self._WhenSimpleTapFunc = function( gesture )
        self:_WhenSimpleTap( gesture )
    end
    self._WhenPinchFunc = function( gesture )
        self:_WhenPinch( gesture )
    end
    self._WhenSwipeFunc = function( gesture )
        self:_WhenSwipe( gesture )
    end

    ---
    EasyTouch.On_SimpleTap( '+', self._WhenSimpleTapFunc )  -- 快速单击, 尾后帧

    EasyTouch.On_SwipeStart( '+', self._WhenSwipeFunc )  -- 滑动 首帧
    EasyTouch.On_Swipe(      '+', self._WhenSwipeFunc )  -- 滑动 每一帧
    EasyTouch.On_SwipeEnd(   '+', self._WhenSwipeFunc )  -- 滑动 尾后帧


    if IdolLive3D_States.isWindowsPlatform == false then 
        EasyTouch.On_PinchIn( '+', self._WhenPinchFunc ) -- 缩小 每一帧
        EasyTouch.On_PinchOut( '+', self._WhenPinchFunc ) -- 放大 每一帧
    end 
end


function IdolLive3D_Input:_UnregistEvent()
    --  
    EasyTouch.On_SimpleTap( '-', self._WhenSimpleTapFunc )  -- 快速单击, 尾后帧

    EasyTouch.On_SwipeStart( '-', self._WhenSwipeFunc )  -- 滑动 首帧
    EasyTouch.On_Swipe(      '-', self._WhenSwipeFunc )  -- 滑动 每一帧
    EasyTouch.On_SwipeEnd(   '-', self._WhenSwipeFunc )  -- 滑动 尾后帧

    if IdolLive3D_States.isWindowsPlatform == false then 
        EasyTouch.On_PinchIn( '-', self._WhenPinchFunc ) -- 缩小 每一帧
        EasyTouch.On_PinchOut( '-', self._WhenPinchFunc ) -- 放大 每一帧
    end 
    
    self._WhenSimpleTapFunc = nil
    self._WhenPinchFunc = nil
    self.OnTwistFunc = nil
    self._WhenSwipeFunc = nil
end




-- gesture: Vector2 posSS, 像素为单位, 左下角[0,0]
function IdolLive3D_Input:_WhenSimpleTap(gesture)
    if gesture.touchCount ~= 1 then 
        return
    end

    if gesture.type == EasyTouch.EvtType.On_SimpleTap then
        if #self.OnSimpleTapCallBacks > 0 then
            for i=1,#self.OnSimpleTapCallBacks do 
                self.OnSimpleTapCallBacks[i]( gesture )
            end
        end
    end
end


-- gesture.swipeVector 无需叠加 Time.deltaTime, 它记录的是上一帧划过屏幕的像素个数, 自己已经含有帧信息了
-- gesture: Vector2 posSS, 像素为单位, 左下角[0,0]
function IdolLive3D_Input:_WhenSwipe(gesture)
    if gesture.touchCount ~= 1 then 
        return
    end
    -- 监听: swipeVector
    --print("_WhenSwipe")
    if gesture.type == EasyTouch.EvtType.On_SwipeStart then
    elseif gesture.type == EasyTouch.EvtType.On_Swipe then

        if #self.OnSwipeCallBacks > 0 then
            for i=1,#self.OnSwipeCallBacks do 
                --printError("调用 OnSwipeCallBacks")
                self.OnSwipeCallBacks[i]( gesture )
            end
        end

    elseif gesture.type == EasyTouch.EvtType.On_SwipeEnd then
    end
end


-- gesture: Vector2 posSS, 像素为单位, 左下角[0,0]
function IdolLive3D_Input:_WhenPinch(gesture)
    if gesture.touchCount ~= 2 then 
        return
    end

    print("_WhenPinch")

    if gesture.type == EasyTouch.EvtType.On_PinchIn then

        if #self.OnPinchCallBacks > 0 then
            for i=1,#self.OnPinchCallBacks do 
                self.OnPinchCallBacks[i](  gesture.deltaPinch )
            end
        end

    elseif gesture.type == EasyTouch.EvtType.On_PinchOut then

        if #self.OnPinchCallBacks > 0 then
            for i=1,#self.OnPinchCallBacks do 
                self.OnPinchCallBacks[i]( - gesture.deltaPinch )
            end
        end
 
    end
end





